/**
 * Prisma Database Seed (idempotent — safe to re-run)
 *
 * Seeds:
 * 1. First SUPER_ADMIN (2FA enrolment is forced at first login)
 * 2. River stretches (Rishikesh)
 * 3. Non-production only: a LIVE dev vendor with an OWNER member, one LIVE trip,
 *    daily departure templates and a commission row. Slots are generated by the
 *    API's slots.generate job (runs at startup and hourly).
 *
 * Run: npm run prisma:seed --workspace=apps/api
 */
import { PrismaClient } from '@prisma/client';
import * as bcrypt from 'bcrypt';

const prisma = new PrismaClient();
const isProduction = process.env.APP_ENV === 'production';

async function main() {
  console.log('Seeding RaftNow database...');

  // ── Admin ──────────────────────────────────────────────────────────────────
  const adminEmail = (process.env.SEED_ADMIN_EMAIL ?? 'admin@raftnow.in').toLowerCase();
  let adminPassword = process.env.SEED_ADMIN_PASSWORD;
  if (!adminPassword) {
    if (isProduction) throw new Error('SEED_ADMIN_PASSWORD is required when APP_ENV=production');
    adminPassword = 'ChangeMe-Dev-Only-123';
    console.warn(`[seed] SEED_ADMIN_PASSWORD not set — using the development default for ${adminEmail}. Never use this outside local development.`);
  }
  if (adminPassword.length < 12) throw new Error('SEED_ADMIN_PASSWORD must be at least 12 characters');

  const admin = await prisma.admin.upsert({
    where: { email: adminEmail },
    update: {},
    create: { email: adminEmail, name: 'Seed Super Admin', password_hash: await bcrypt.hash(adminPassword, 12), role: 'SUPER_ADMIN' },
  });
  console.log(`Admin ready: ${adminEmail} (TOTP enrolment required at first login)`);

  // ── Stretches ──────────────────────────────────────────────────────────────
  const stretches = [
    { name: 'Brahmpuri → Rishikesh', distance_km: 9, grade: 'Grade II-III', duration_minutes: 60, put_in_point: 'Brahmpuri', take_out_point: 'Rishikesh', min_age: 12 },
    { name: 'Shivpuri → Rishikesh', distance_km: 16, grade: 'Grade III-IV', duration_minutes: 120, put_in_point: 'Shivpuri', take_out_point: 'Rishikesh (NIM Beach)', min_age: 14 },
    { name: 'Kodiyala → Rishikesh', distance_km: 26, grade: 'Grade IV+', duration_minutes: 150, put_in_point: 'Kodiyala', take_out_point: 'Marine Drive', min_age: 18 },
    { name: 'Marine Drive → Rishikesh', distance_km: 36, grade: 'Grade IV', duration_minutes: 180, put_in_point: 'Marine Drive', take_out_point: 'Rishikesh (NIM Beach)', min_age: 18 },
  ];
  for (const s of stretches) {
    await prisma.stretch.upsert({ where: { name: s.name }, update: {}, create: { ...s, active: true } });
  }
  console.log(`${stretches.length} stretches ready`);

  if (isProduction) {
    console.log('Production seed complete (no sample vendor).');
    return;
  }

  // ── Development vendor ─────────────────────────────────────────────────────
  const existing = await prisma.vendor.findFirst({ where: { legal_name: 'Dev Rafting Co' } });
  if (existing) {
    console.log('Dev vendor already exists');
    return;
  }
  const shivpuri = await prisma.stretch.findUniqueOrThrow({ where: { name: 'Shivpuri → Rishikesh' } });
  const nextYear = new Date();
  nextYear.setUTCFullYear(nextYear.getUTCFullYear() + 1);

  const vendor = await prisma.vendor.create({
    data: {
      legal_name: 'Dev Rafting Co',
      display_name: 'Adventure Raft Rishikesh (DEV)',
      owner_name: 'Ravi Kumar',
      phone: '+919876543210',
      email: 'ravi@devrafting.test',
      address: 'Camp Shivpuri, Badrinath Road',
      address_city: 'Rishikesh',
      address_state: 'Uttarakhand',
      address_postal_code: '249192',
      business_type: 'proprietorship',
      licence_number: 'URDB-DEV-0001',
      licence_expiry: nextYear,
      licence_verified: true,
      licence_verified_at: new Date(),
      licence_verified_by: admin.id,
      status: 'LIVE',
      approved_at: new Date(),
      // No Razorpay linked account: payouts stay ON_HOLD (NO_LINKED_ACCOUNT)
      // until an admin completes Route onboarding with real credentials.
    },
  });

  // OWNER member usable with AUTH_DEV_BYPASS: token "dev:vendor-owner:+919876543210"
  await prisma.vendorMember.create({
    data: { vendor_id: vendor.id, firebase_uid: 'dev_vendor-owner', phone: '+919876543210', name: 'Ravi Kumar', role: 'OWNER' },
  });

  const trip = await prisma.trip.create({
    data: {
      vendor_id: vendor.id,
      stretch_id: shivpuri.id,
      title: 'Shivpuri Rafting Adventure',
      description: '16 km of Grade III-IV rapids from Shivpuri to NIM Beach.',
      duration_minutes: 120,
      inclusions: ['Life jacket', 'Helmet', 'Certified guide', 'Paddle'],
      exclusions: ['Personal items', 'Photography'],
      meeting_point: 'Camp Shivpuri entrance gate',
      meeting_lat: 30.0867,
      meeting_lng: 78.3498,
      min_age: 14,
      raft_capacity: 8,
      per_seat_price_paise: 80000n, // ₹800
      private_raft_price_paise: 550000n, // ₹5,500
      status: 'LIVE',
    },
  });
  for (const time of ['07:00', '10:00', '14:00']) {
    await prisma.slotTemplate.create({ data: { trip_id: trip.id, departure_time: time, days_of_week: [], rafts_count: 3, active: true } });
  }
  await prisma.vendorCommission.create({
    data: { vendor_id: vendor.id, commission_bps: 1000, effective_from: new Date('2024-01-01T00:00:00Z'), set_by_admin: admin.id },
  });
  console.log('Dev vendor, OWNER member, trip, departures and commission created');
}

main()
  .then(() => console.log('Seed complete'))
  .catch((e) => {
    console.error('Seed failed:', e instanceof Error ? e.message : e);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());
